import{_ as l,o as i,c as a,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph Performance Meeting 2021-04-29","description":"","frontmatter":{"title":"Ceph Performance Meeting 2021-04-29","date":"2021-04-29T00:00:00.000Z","updated":"2021-04-30T00:00:00.000Z","tags":["Ceph","Performance Optimization","Distributed Storage","Blue Store","Deadlock","Cache Optimization"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Performance_Meeting_2021-04-29.md","filePath":"posts/2021/Ceph_Performance_Meeting_2021-04-29.md","lastUpdated":1780460162000}'),r={name:"posts/2021/Ceph_Performance_Meeting_2021-04-29.md"};function o(n,e,s,u,h,d){return i(),a("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h4><ul><li><strong>日期与时间</strong>: 2021年4月29日，会议稍晚但按计划进行。</li><li><strong>参与者</strong>: 主要参与者包括Gabby、Kifu、Adam等。</li></ul><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>死锁问题</strong>:</p><ul><li>近期合并的Blue Store写过程锁优化PR引发了死锁问题，Kifu尝试解决但出现死锁，决定回滚。</li></ul></li><li><p><strong>缓存线优化</strong>:</p><ul><li>讨论了缓存线优化和分片行为，特别是与缓存线统计相关的PR，这对于确定如何进一步优化存储行为非常重要。</li></ul></li><li><p><strong>RGW压缩PR</strong>:</p><ul><li>讨论了RGW压缩的PR，目前尚未合并，但已准备好。</li></ul></li><li><p><strong>Crimson客户端请求处理并行化PR</strong>:</p><ul><li>该PR正在测试中，已重新基于，但近期无进一步进展。</li></ul></li><li><p><strong>BlueFS锁优化</strong>:</p><ul><li>讨论了BlueFS锁优化的问题，特别是多线程环境下的性能和安全性，需要进一步分析和确定锁策略。</li></ul></li><li><p><strong>性能测试和优化</strong>:</p><ul><li>讨论了性能测试的重要性，特别是如何捕捉和避免潜在的性能下降，强调标准化测试环境和实时监控性能指标的必要性。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li><strong>回滚PR</strong>: 由于死锁问题，决定回滚最近的Blue Store优化PR。</li><li><strong>继续测试和优化</strong>: 继续对Crimson客户端请求处理并行化PR进行测试和优化。</li><li><strong>性能监控</strong>: 需要建立更有效的性能监控和测试机制，以避免未来的性能问题。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li><strong>性能分析</strong>: 对Luminous和Master的性能进行详细分析，特别是关于OMAP操作的性能。</li><li><strong>锁优化</strong>: 继续研究和优化BlueFS的锁机制，确保多线程环境下的安全和性能。</li><li><strong>标准化测试</strong>: 开发和实施标准化的性能测试流程，确保测试结果的可比性和可靠性。</li></ul><h4 id="其他讨论" tabindex="-1">其他讨论 <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论&quot;">​</a></h4><ul><li><strong>硬件配置</strong>: 讨论了不同硬件配置下的性能表现，特别是NVMe和HDD的差异。</li><li><strong>未来方向</strong>: 讨论了未来可能的技术方向，如Crimson存储引擎的进一步开发和应用。</li></ul><h4 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h4><p>会议强调了性能优化的重要性，特别是在分布式存储系统中。通过详细的性能分析和标准化的测试流程，可以确保系统的稳定性和高效性。同时，对锁机制的优化也是提高系统性能的关键。</p><h3 id="标签" tabindex="-1">标签 <a class="header-anchor" href="#标签" aria-label="Permalink to &quot;标签&quot;">​</a></h3><ul><li>[Ceph]</li><li>[Performance Optimization]</li><li>[Distributed Storage]</li><li>[Blue Store]</li><li>[Deadlock]</li><li>[Cache Optimization]</li></ul>',15)])])}const c=l(r,[["render",o]]);export{p as __pageData,c as default};
